css.fulfillment-workbench.css:
.dmwcfw-workspace {
	--dmwcfw-ink: #251d26;
	--dmwcfw-ink-soft: #665e66;
	--dmwcfw-plum: #35203a;
	--dmwcfw-plum-deep: #28152e;
	--dmwcfw-purple: #7f54b3;
	--dmwcfw-purple-dark: #67408f;
	--dmwcfw-lilac: #eee8ef;
	--dmwcfw-paper: #fcfbf8;
	--dmwcfw-stone: #f2efe9;
	--dmwcfw-line: #dcd6cf;
	--dmwcfw-line-dark: #c9c0c9;
	--dmwcfw-green: #1f7553;
	--dmwcfw-green-pale: #dceee4;
	--dmwcfw-amber: #9a5b16;
	--dmwcfw-amber-pale: #f7ead2;
	background: var(--dmwcfw-paper);
	box-sizing: border-box;
	color: var(--dmwcfw-ink);
	container-name: dmwcfw;
	container-type: inline-size;
	font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
	height: 100%;
	min-height: 0;
	overflow: hidden;
}

.dmwcfw-workspace *,
.dmwcfw-workspace *::before,
.dmwcfw-workspace *::after {
	box-sizing: border-box;
}

.dmwcfw-workspace button,
.dmwcfw-workspace input {
	font: inherit;
}

.dmwcfw-workspace button,
.dmwcfw-workspace a {
	-webkit-tap-highlight-color: transparent;
}

.dmwcfw-workspace button:focus-visible,
.dmwcfw-workspace a:focus-visible,
.dmwcfw-workspace input:focus-visible {
	outline: 3px solid rgb(127 84 179 / 34%);
	outline-offset: 2px;
}

.dmwcfw-app {
	display: grid;
	grid-template-rows: 66px minmax(0, 1fr);
	height: 100%;
	position: relative;
}

.dmwcfw-topbar {
	align-items: center;
	background: var(--dmwcfw-plum-deep);
	color: #fff;
	display: grid;
	grid-template-columns: minmax(235px, 270px) minmax(220px, 1fr) auto;
	min-width: 0;
	padding: 0 18px 0 14px;
	position: relative;
	z-index: 20;
}

.dmwcfw-brand {
	align-items: center;
	display: flex;
	gap: 11px;
	min-width: 0;
}

.dmwcfw-brand__mark,
.dmwcfw-boot__mark {
	align-items: center;
	background: #96588a;
	border: 1px solid rgb(255 255 255 / 26%);
	color: #fff;
	display: inline-flex;
	font-family: Georgia, serif;
	font-size: 22px;
	font-style: italic;
	font-weight: 700;
	height: 40px;
	justify-content: center;
	width: 40px;
}

.dmwcfw-brand > span:last-child {
	display: flex;
	flex-direction: column;
	min-width: 0;
}

.dmwcfw-brand strong {
	font-size: 14px;
	letter-spacing: 0.01em;
	line-height: 1.25;
}

.dmwcfw-brand small {
	color: #bdb0c0;
	font-size: 10px;
	letter-spacing: 0.12em;
	line-height: 1.5;
	text-transform: uppercase;
}

.dmwcfw-topbar__focus {
	align-items: baseline;
	border-left: 1px solid rgb(255 255 255 / 14%);
	display: flex;
	gap: 11px;
	justify-self: start;
	padding-left: 22px;
}

.dmwcfw-topbar__focus > span {
	color: #bdb0c0;
	font-size: 11px;
	letter-spacing: 0.08em;
	text-transform: uppercase;
}

.dmwcfw-topbar__focus strong {
	font-family: Georgia, "Times New Roman", serif;
	font-size: 17px;
	font-weight: 500;
}

.dmwcfw-topbar__tools {
	align-items: center;
	display: flex;
	gap: 8px;
}

.dmwcfw-sync-label {
	color: #bdb0c0;
	font-size: 11px;
	margin-right: 2px;
}

.dmwcfw-icon-button,
.dmwcfw-panel-button {
	align-items: center;
	background: transparent;
	border: 1px solid rgb(255 255 255 / 22%);
	color: #fff;
	cursor: pointer;
	display: inline-flex;
	height: 34px;
	justify-content: center;
}

.dmwcfw-icon-button {
	width: 34px;
}

.dmwcfw-icon-button:hover,
.dmwcfw-panel-button:hover {
	background: rgb(255 255 255 / 10%);
}

.dmwcfw-icon-button .dashicons {
	font-size: 16px;
	height: 16px;
	width: 16px;
}

.dmwcfw-workspace.is-busy .dmwcfw-icon-button .dashicons {
	animation: dmwcfw-spin 900ms linear infinite;
}

.dmwcfw-panel-button {
	display: none;
	font-size: 11px;
	font-weight: 650;
	letter-spacing: 0.05em;
	padding: 0 11px;
	text-transform: uppercase;
}

.dmwcfw-body {
	display: grid;
	grid-template-columns: minmax(245px, 270px) minmax(430px, 1fr) minmax(280px, 322px);
	min-height: 0;
	position: relative;
}

.dmwcfw-queue,
.dmwcfw-detail,
.dmwcfw-action {
	min-height: 0;
	overflow: auto;
}

.dmwcfw-queue {
	background: var(--dmwcfw-lilac);
	border-right: 1px solid var(--dmwcfw-line-dark);
	display: flex;
	flex-direction: column;
	padding: 22px 14px 14px;
}

.dmwcfw-queue__header,
.dmwcfw-action__header {
	align-items: flex-start;
	display: flex;
	justify-content: space-between;
}

.dmwcfw-eyebrow {
	color: var(--dmwcfw-purple-dark);
	display: block;
	font-size: 10px;
	font-weight: 750;
	letter-spacing: 0.13em;
	line-height: 1.25;
	text-transform: uppercase;
}

.dmwcfw-queue h2,
.dmwcfw-action h2,
.dmwcfw-section h2 {
	font-family: Georgia, "Times New Roman", serif;
	font-weight: 500;
	margin: 3px 0 0;
}

.dmwcfw-queue h2 {
	font-size: 25px;
}

.dmwcfw-close-panel {
	background: transparent;
	border: 0;
	color: var(--dmwcfw-ink-soft);
	cursor: pointer;
	display: none;
	font-size: 26px;
	line-height: 1;
	padding: 0 2px;
}

.dmwcfw-tabs {
	display: grid;
	grid-template-columns: repeat(3, 1fr);
	margin: 18px 0 13px;
}

.dmwcfw-tabs button {
	background: transparent;
	border: 0;
	border-bottom: 2px solid var(--dmwcfw-line-dark);
	color: var(--dmwcfw-ink-soft);
	cursor: pointer;
	font-size: 11px;
	font-weight: 650;
	padding: 8px 2px 9px;
	text-align: center;
}

.dmwcfw-tabs button span {
	background: rgb(53 32 58 / 8%);
	color: var(--dmwcfw-ink);
	display: inline-flex;
	font-size: 9px;
	justify-content: center;
	margin-left: 2px;
	min-width: 17px;
	padding: 2px 4px;
}

.dmwcfw-tabs button:hover {
	color: var(--dmwcfw-ink);
}

.dmwcfw-tabs button.is-active {
	border-bottom-color: var(--dmwcfw-purple);
	color: var(--dmwcfw-purple-dark);
}

.dmwcfw-search {
	align-items: center;
	background: #fff;
	border: 1px solid var(--dmwcfw-line-dark);
	display: flex;
	height: 38px;
	padding: 0 9px;
}

.dmwcfw-search .dashicons {
	color: #827984;
	font-size: 15px;
	height: 15px;
	width: 15px;
}

.dmwcfw-search input {
	background: transparent;
	border: 0;
	box-shadow: none;
	color: var(--dmwcfw-ink);
	font-size: 12px;
	height: 100%;
	min-width: 0;
	outline: 0;
	padding: 0 7px;
	width: 100%;
}

.dmwcfw-search kbd,
.dmwcfw-shortcuts kbd {
	background: #f5f2f5;
	border: 1px solid #d1c9d2;
	box-shadow: 0 1px 0 #bfb6c0;
	color: #6f6570;
	font-family: inherit;
	font-size: 9px;
	line-height: 1;
	padding: 3px 5px;
}

.dmwcfw-queue__summary {
	align-items: center;
	color: var(--dmwcfw-ink-soft);
	display: flex;
	font-size: 10px;
	justify-content: space-between;
	letter-spacing: 0.02em;
	padding: 13px 2px 8px;
}

.dmwcfw-queue__summary strong {
	color: var(--dmwcfw-ink);
	font-size: 11px;
	font-weight: 650;
}

.dmwcfw-order-list {
	display: flex;
	flex: 1;
	flex-direction: column;
	gap: 7px;
	min-height: 0;
	overflow: auto;
	padding: 2px 2px 10px;
}

.dmwcfw-order-card {
	align-items: stretch;
	background: rgb(255 255 255 / 62%);
	border: 1px solid transparent;
	color: var(--dmwcfw-ink);
	cursor: pointer;
	display: grid;
	grid-template-columns: 29px 1fr;
	min-height: 82px;
	padding: 0;
	text-align: left;
	transition: background 120ms ease, border-color 120ms ease, transform 120ms ease;
	width: 100%;
}

.dmwcfw-order-card:hover {
	background: #fff;
	border-color: #d3cad4;
	transform: translateX(2px);
}

.dmwcfw-order-card.is-selected {
	background: #fff;
	border-color: var(--dmwcfw-purple);
	box-shadow: 3px 3px 0 rgb(127 84 179 / 12%);
}

.dmwcfw-order-card__index {
	align-items: center;
	border-right: 1px solid rgb(53 32 58 / 10%);
	color: #998f99;
	display: flex;
	font-family: Georgia, serif;
	font-size: 10px;
	justify-content: center;
	letter-spacing: 0.04em;
}

.dmwcfw-order-card.is-selected .dmwcfw-order-card__index {
	background: var(--dmwcfw-purple);
	border-color: var(--dmwcfw-purple);
	color: #fff;
}

.dmwcfw-order-card__body {
	display: flex;
	flex-direction: column;
	gap: 4px;
	justify-content: center;
	min-width: 0;
	padding: 10px 11px;
}

.dmwcfw-order-card__top,
.dmwcfw-order-card__meta {
	align-items: center;
	display: flex;
	justify-content: space-between;
}

.dmwcfw-order-card__top strong {
	font-family: Georgia, serif;
	font-size: 14px;
	font-weight: 600;
}

.dmwcfw-order-card__top b {
	font-size: 11px;
	font-weight: 700;
}

.dmwcfw-order-card__customer {
	font-size: 12px;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.dmwcfw-order-card__meta {
	color: #817881;
	font-size: 9px;
	letter-spacing: 0.02em;
}

.dmwcfw-order-card__meta .is-waiting {
	color: var(--dmwcfw-amber);
	font-weight: 700;
}

.dmwcfw-order-card--skeleton {
	animation: dmwcfw-pulse 1.2s ease-in-out infinite alternate;
	background: rgb(255 255 255 / 46%);
	border-color: transparent;
	cursor: default;
}

.dmwcfw-empty-queue {
	align-items: center;
	color: var(--dmwcfw-ink-soft);
	display: flex;
	flex: 1;
	flex-direction: column;
	justify-content: center;
	padding: 34px 20px;
	text-align: center;
}

.dmwcfw-empty-queue .dashicons {
	color: var(--dmwcfw-green);
	font-size: 28px;
	height: 28px;
	margin-bottom: 10px;
	width: 28px;
}

.dmwcfw-empty-queue strong {
	color: var(--dmwcfw-ink);
	font-family: Georgia, serif;
	font-size: 18px;
	font-weight: 500;
}

.dmwcfw-empty-queue p {
	font-size: 11px;
	line-height: 1.5;
	margin: 6px 0 12px;
}

.dmwcfw-empty-queue button {
	background: transparent;
	border: 0;
	color: var(--dmwcfw-purple-dark);
	cursor: pointer;
	font-size: 11px;
	font-weight: 700;
	text-decoration: underline;
}

.dmwcfw-detail {
	background: var(--dmwcfw-paper);
	position: relative;
}

.dmwcfw-detail__inner {
	margin: 0 auto;
	max-width: 800px;
	padding: 28px clamp(24px, 4vw, 46px) 52px;
}

.dmwcfw-order-heading {
	align-items: flex-start;
	display: flex;
	justify-content: space-between;
}

.dmwcfw-order-heading h1 {
	font-family: Georgia, "Times New Roman", serif;
	font-size: clamp(34px, 4.5vw, 48px);
	font-weight: 500;
	letter-spacing: -0.035em;
	line-height: 1;
	margin: 5px 0 7px;
}

.dmwcfw-order-heading p {
	color: var(--dmwcfw-ink-soft);
	font-size: 11px;
	margin: 0;
}

.dmwcfw-status-pill {
	background: var(--dmwcfw-amber-pale);
	border: 1px solid #e1c28d;
	color: var(--dmwcfw-amber);
	font-size: 9px;
	font-weight: 750;
	letter-spacing: 0.09em;
	margin-top: 5px;
	padding: 7px 10px;
	text-transform: uppercase;
}

.dmwcfw-status-pill--completed {
	background: var(--dmwcfw-green-pale);
	border-color: #afd0be;
	color: var(--dmwcfw-green);
}

.dmwcfw-status-pill--on-hold {
	background: #eee8ef;
	border-color: #cfc1d1;
	color: var(--dmwcfw-purple-dark);
}

.dmwcfw-customer-strip {
	align-items: center;
	border-bottom: 1px solid var(--dmwcfw-line);
	border-top: 1px solid var(--dmwcfw-line);
	display: grid;
	gap: 14px;
	grid-template-columns: auto minmax(120px, 1fr) minmax(150px, 1.35fr) minmax(100px, .75fr);
	margin-top: 24px;
	padding: 14px 0;
}

.dmwcfw-avatar {
	align-items: center;
	background: var(--dmwcfw-plum);
	color: #fff;
	display: flex;
	font-family: Georgia, serif;
	font-size: 13px;
	height: 35px;
	justify-content: center;
	width: 35px;
}

.dmwcfw-customer-strip > div {
	display: flex;
	flex-direction: column;
	min-width: 0;
}

.dmwcfw-customer-strip small,
.dmwcfw-line-item small,
.dmwcfw-progress small {
	color: #867d85;
	font-size: 9px;
	letter-spacing: 0.02em;
}

.dmwcfw-customer-strip strong,
.dmwcfw-customer-strip a,
.dmwcfw-customer-strip span:not(.dmwcfw-avatar) {
	color: var(--dmwcfw-ink);
	font-size: 11px;
	overflow: hidden;
	text-decoration: none;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.dmwcfw-customer-strip a:hover {
	color: var(--dmwcfw-purple-dark);
	text-decoration: underline;
}

.dmwcfw-section {
	margin-top: 29px;
}

.dmwcfw-section__heading {
	align-items: flex-end;
	display: flex;
	gap: 12px;
}

.dmwcfw-section h2 {
	font-size: 20px;
}

.dmwcfw-section__rule {
	border-top: 1px solid var(--dmwcfw-line);
	flex: 1;
	margin-bottom: 5px;
}

.dmwcfw-pick-list ul,
.dmwcfw-timeline {
	list-style: none;
	margin: 13px 0 0;
	padding: 0;
}

.dmwcfw-line-item {
	align-items: center;
	border-bottom: 1px solid var(--dmwcfw-line);
	display: grid;
	gap: 12px;
	grid-template-columns: 42px minmax(0, 1fr) 40px auto;
	min-height: 66px;
	padding: 9px 2px;
}

.dmwcfw-line-item__thumb {
	align-items: center;
	background: #e7e1d7;
	border: 1px solid #d5cdbf;
	color: #6d645b;
	display: flex;
	font-family: Georgia, serif;
	font-size: 16px;
	height: 40px;
	justify-content: center;
	width: 40px;
}

.dmwcfw-line-item__name,
.dmwcfw-line-item__qty {
	display: flex;
	flex-direction: column;
}

.dmwcfw-line-item__name strong {
	font-size: 12px;
	font-weight: 650;
	line-height: 1.35;
}

.dmwcfw-line-item__qty {
	align-items: center;
}

.dmwcfw-line-item__qty strong,
.dmwcfw-line-item__total {
	font-size: 12px;
}

.dmwcfw-line-item__total {
	font-weight: 700;
	text-align: right;
}

.dmwcfw-order-total {
	align-items: baseline;
	display: flex;
	justify-content: flex-end;
	padding-top: 12px;
}

.dmwcfw-order-total span {
	color: var(--dmwcfw-ink-soft);
	font-size: 10px;
	margin-right: 15px;
	text-transform: uppercase;
}

.dmwcfw-order-total strong {
	font-family: Georgia, serif;
	font-size: 19px;
	font-weight: 500;
}

.dmwcfw-detail-grid {
	display: grid;
	gap: 12px;
	grid-template-columns: minmax(180px, .75fr) minmax(250px, 1.25fr);
	margin-top: 28px;
}

.dmwcfw-info-card {
	background: var(--dmwcfw-stone);
	border: 1px solid var(--dmwcfw-line);
	min-height: 135px;
	padding: 16px;
}

.dmwcfw-info-card dl {
	margin: 13px 0 0;
}

.dmwcfw-info-card dl > div {
	border-top: 1px solid #d8d1c7;
	display: flex;
	gap: 10px;
	justify-content: space-between;
	padding: 8px 0;
}

.dmwcfw-info-card dt,
.dmwcfw-info-card dd {
	font-size: 10px;
	margin: 0;
}

.dmwcfw-info-card dt {
	color: var(--dmwcfw-ink-soft);
}

.dmwcfw-info-card dd {
	font-weight: 650;
	text-align: right;
}

.dmwcfw-timeline {
	display: flex;
	flex-direction: column;
	gap: 9px;
}

.dmwcfw-timeline li {
	display: grid;
	gap: 9px;
	grid-template-columns: 8px 1fr;
}

.dmwcfw-timeline li > span {
	background: var(--dmwcfw-purple);
	height: 6px;
	margin-top: 4px;
	width: 6px;
}

.dmwcfw-timeline li div {
	display: flex;
	flex-direction: column;
}

.dmwcfw-timeline strong {
	font-size: 10px;
	font-weight: 600;
	line-height: 1.35;
}

.dmwcfw-timeline small {
	color: var(--dmwcfw-ink-soft);
	font-size: 9px;
	margin-top: 2px;
}

.dmwcfw-empty-detail {
	align-items: center;
	display: flex;
	flex-direction: column;
	height: 100%;
	justify-content: center;
	padding: 40px;
	text-align: center;
}

.dmwcfw-empty-detail__stamp {
	border: 2px solid var(--dmwcfw-line-dark);
	color: #a39aa1;
	font-family: Georgia, serif;
	font-size: 12px;
	letter-spacing: 0.2em;
	padding: 9px 12px 8px 14px;
	transform: rotate(-4deg);
}

.dmwcfw-empty-detail h2 {
	font-family: Georgia, serif;
	font-size: 26px;
	font-weight: 500;
	margin: 18px 0 6px;
}

.dmwcfw-empty-detail p {
	color: var(--dmwcfw-ink-soft);
	font-size: 12px;
	margin: 0;
}

.dmwcfw-action {
	background: var(--dmwcfw-stone);
	border-left: 1px solid var(--dmwcfw-line);
	padding: 24px 20px 20px;
}

.dmwcfw-action h2 {
	font-size: 24px;
}

.dmwcfw-progress {
	list-style: none;
	margin: 23px 0 0;
	padding: 0;
}

.dmwcfw-progress li {
	display: grid;
	gap: 11px;
	grid-template-columns: 27px 1fr;
	min-height: 53px;
	position: relative;
}

.dmwcfw-progress li:not(:last-child)::after {
	background: #cec7bf;
	content: "";
	height: 25px;
	left: 13px;
	position: absolute;
	top: 27px;
	width: 1px;
}

.dmwcfw-progress li > span {
	align-items: center;
	background: transparent;
	border: 1px solid #bcb4ac;
	color: #8c837b;
	display: flex;
	font-size: 9px;
	height: 27px;
	justify-content: center;
	position: relative;
	width: 27px;
	z-index: 1;
}

.dmwcfw-progress li.is-done > span {
	background: var(--dmwcfw-green);
	border-color: var(--dmwcfw-green);
	color: #fff;
}

.dmwcfw-progress li.is-current > span {
	background: var(--dmwcfw-purple);
	border-color: var(--dmwcfw-purple);
	box-shadow: 0 0 0 4px rgb(127 84 179 / 12%);
	color: #fff;
}

.dmwcfw-progress li > div {
	display: flex;
	flex-direction: column;
	padding-top: 1px;
}

.dmwcfw-progress strong {
	font-size: 11px;
	font-weight: 650;
}

.dmwcfw-address-card {
	background: var(--dmwcfw-paper);
	border: 1px solid var(--dmwcfw-line);
	margin-top: 12px;
	padding: 15px;
}

.dmwcfw-address-card__top {
	align-items: center;
	display: flex;
	justify-content: space-between;
}

.dmwcfw-address-card__top button {
	background: transparent;
	border: 0;
	color: var(--dmwcfw-purple-dark);
	cursor: pointer;
	font-size: 10px;
	font-weight: 700;
	padding: 2px;
	text-decoration: underline;
}

.dmwcfw-address-card address {
	color: #4e464d;
	font-size: 11px;
	font-style: normal;
	line-height: 1.55;
	margin-top: 11px;
}

.dmwcfw-address-card p {
	border-top: 1px solid var(--dmwcfw-line);
	color: var(--dmwcfw-ink-soft);
	font-size: 10px;
	line-height: 1.45;
	margin: 12px 0 0;
	padding-top: 10px;
}

.dmwcfw-address-card p strong {
	color: var(--dmwcfw-ink);
	display: block;
