(function() {
  "use strict";
  const WINDOW_ID = "desktop-mode-fulfillment-workbench-for-woocommerce";
  const COMMAND_OWNER = "desktop-mode-fulfillment-workbench-for-woocommerce";
  function translate(text) {
    return window.wp?.i18n?.__(
      text,
      "desktop-mode-fulfillment-workbench-for-woocommerce"
    ) ?? text;
  }
  function escapeHtml(value) {
    return String(value ?? "").replace(
      /[&<>'"]/g,
      (character) => ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        "'": "&#039;",
        '"': "&quot;"
      })[character] ?? character
    );
  }
  function initials(name) {
    const parts = name.trim().split(/\s+/).filter(Boolean);
    return (parts[0]?.[0] ?? "W") + (parts[1]?.[0] ?? "");
  }
  function pluralize(count, singular, plural = `${singular}s`) {
    return `${count} ${count === 1 ? singular : plural}`;
  }
  function getConfig(api2) {
    const config = api2.getWindowConfig(WINDOW_ID);
    if (!config?.ordersUrl || !config.restNonce) {
      throw new Error(translate("Woo Dispatch configuration is unavailable."));
    }
    return config;
  }
  class DispatchWorkbench {
    constructor(root, config) {
      this.status = "processing";
      this.orders = [];
      this.counts = {
        processing: 0,
        "on-hold": 0,
        completed: 0
      };
      this.selectedId = null;
      this.search = "";
      this.searchTimer = null;
      this.activeRequest = null;
      this.busy = false;
      this.confirmCompleteId = null;
      this.lastUpdated = "";
      this.loadOrders = async () => {
        this.activeRequest?.abort();
        const controller = new AbortController();
        this.activeRequest = controller;
        this.busy = true;
        this.render();
        try {
          const url = new URL(this.config.ordersUrl, window.location.href);
          url.searchParams.set("status", this.status);
          if (this.search) {
            url.searchParams.set("search", this.search);
          }
          const response = await fetch(url.toString(), {
            credentials: "same-origin",
            headers: {
              Accept: "application/json",
              "X-WP-Nonce": this.config.restNonce
            },
            signal: controller.signal
          });
          const data = await response.json();
          if (!response.ok) {
            throw new Error(data.message || "Orders could not be loaded.");
          }
          this.orders = data.orders;
          this.counts = data.counts;
          this.lastUpdated = new Intl.DateTimeFormat(void 0, {
            hour: "numeric",
            minute: "2-digit"
          }).format(new Date(data.generatedAt));
          if (!this.orders.some((order) => order.id === this.selectedId)) {
            this.selectedId = this.orders[0]?.id ?? null;
          }
        } catch (error) {
          if (!controller.signal.aborted) {
            this.orders = [];
            this.selectedId = null;
            this.announce(error instanceof Error ? error.message : "Orders could not be loaded.");
          }
        } finally {
          if (this.activeRequest === controller) {
            this.activeRequest = null;
            this.busy = false;
            this.render();
          }
        }
      };
      this.updateStatus = async (order, nextStatus) => {
        if (this.busy) {
          return;
        }
        this.busy = true;
        this.renderHeader();
        this.renderActions();
        try {
          const response = await fetch(`${this.config.ordersUrl}/${order.id}/status`, {
            method: "POST",
            credentials: "same-origin",
            headers: {
              Accept: "application/json",
              "Content-Type": "application/json",
              "X-WP-Nonce": this.config.restNonce
            },
            body: JSON.stringify({ status: nextStatus })
          });
          const data = await response.json();
          if (!response.ok) {
            throw new Error(data.message || "The order could not be updated.");
          }
          this.confirmCompleteId = null;
          this.busy = false;
          await this.loadOrders();
          this.announce(data.message);
        } catch (error) {
          this.busy = false;
          this.render();
          this.announce(error instanceof Error ? error.message : "The order could not be updated.");
        }
      };
      this.copyAddress = async (order) => {
        const text = order.shipping.lines.join("\n");
        try {
          await navigator.clipboard.writeText(text);
          this.announce("Shipping address copied.");
        } catch {
          this.announce("Copy was blocked. Select the address manually.");
        }
      };
      this.onClick = (event) => {
        const target = event.target.closest("button, [data-action]");
        if (!target) {
          return;
        }
        const status = target.dataset.status;
        if (status) {
          this.status = status;
          this.selectedId = null;
          this.confirmCompleteId = null;
          void this.loadOrders();
          return;
        }
        if (target.dataset.orderId) {
          this.selectedId = Number(target.dataset.orderId);
          this.confirmCompleteId = null;
          this.root.classList.remove("show-queue");
          this.renderQueue();
          this.renderDetail();
          this.renderActions();
          return;
        }
        const order = this.selectedOrder();
        switch (target.dataset.action) {
          case "refresh":
            void this.loadOrders();
            break;
          case "clear-search": {
            this.search = "";
            const input = this.root.querySelector("[data-dmwcfw-search]");
            if (input) {
              input.value = "";
            }
            void this.loadOrders();
            break;
          }
          case "prepare-complete":
            if (order) {
              this.confirmCompleteId = order.id;
              this.renderActions();
            }
            break;
          case "cancel-complete":
            this.confirmCompleteId = null;
            this.renderActions();
            break;
          case "change-status":
            if (order && target.dataset.nextStatus) {
              void this.updateStatus(order, target.dataset.nextStatus);
            }
            break;
          case "copy-address":
            if (order) {
              void this.copyAddress(order);
            }
            break;
          case "toggle-queue":
            this.root.classList.toggle("show-queue");
            this.root.classList.remove("show-actions");
            break;
          case "toggle-actions":
            this.root.classList.toggle("show-actions");
            this.root.classList.remove("show-queue");
            break;
          case "close-panels":
            this.root.classList.remove("show-queue", "show-actions");
            break;
        }
      };
      this.onInput = (event) => {
        const input = event.target;
        if (!input.matches("[data-dmwcfw-search]")) {
          return;
        }
        this.search = input.value.trim();
        if (this.searchTimer) {
          window.clearTimeout(this.searchTimer);
        }
        this.searchTimer = window.setTimeout(() => void this.loadOrders(), 280);
      };
      this.onKeyDown = (event) => {
        if (this.root.offsetParent === null) {
          return;
        }
        const target = event.target;
        const editing = target.matches("input, textarea, select") || target.isContentEditable;
        if (event.key === "/" && !editing) {
          event.preventDefault();
          this.root.querySelector("[data-dmwcfw-search]")?.focus();
          return;
        }
        if (editing) {
          return;
        }
        if (event.key.toLowerCase() === "j") {
          event.preventDefault();
          this.selectRelative(1);
        } else if (event.key.toLowerCase() === "k") {
          event.preventDefault();
          this.selectRelative(-1);
        } else if (event.key.toLowerCase() === "r") {
          event.preventDefault();
          void this.loadOrders();
        } else if (event.key === "Escape") {
          this.confirmCompleteId = null;
          this.root.classList.remove("show-queue", "show-actions");
          this.renderActions();
        }
      };
      this.onWindowClosed = (event) => {
        const detail = event.detail;
        if (detail?.windowId !== this.windowId) {
          return;
        }
        this.activeRequest?.abort();
        this.root.removeEventListener("click", this.onClick);
        this.root.removeEventListener("input", this.onInput);
        document.removeEventListener("keydown", this.onKeyDown);
        document.removeEventListener("desktop-mode-window-closed", this.onWindowClosed);
      };
      this.root = root;
      this.config = config;
      this.windowId = root.closest(".desktop-mode-window")?.id.replace(/^wp-window-/, "") ?? null;
    }
    start() {
      this.renderShell();
      this.root.addEventListener("click", this.onClick);
      this.root.addEventListener("input", this.onInput);
      document.addEventListener("keydown", this.onKeyDown);
      document.addEventListener("desktop-mode-window-closed", this.onWindowClosed);
      void this.loadOrders();
    }
    selectedOrder() {
      return this.orders.find((order) => order.id === this.selectedId) ?? null;
    }
    renderShell() {
      this.root.innerHTML = `
			<div class="dmwcfw-app">
				<header class="dmwcfw-topbar">
					<div class="dmwcfw-brand">
						<span class="dmwcfw-brand__mark" aria-hidden="true">W</span>
						<span><strong>Woo Dispatch</strong><small>Fulfillment desk</small></span>
					</div>
					<div class="dmwcfw-topbar__focus">
						<span>Today’s focus</span>
						<strong><span data-dmwcfw-ready-count>—</span> ready to ship</strong>
					</div>
					<div class="dmwcfw-topbar__tools">
						<span class="dmwcfw-sync-label" data-dmwcfw-sync-label>Connecting…</span>
						<button class="dmwcfw-icon-button" type="button" data-action="refresh" aria-label="Refresh orders" title="Refresh orders">
							<span class="dashicons dashicons-update" aria-hidden="true"></span>
						</button>
						<button class="dmwcfw-panel-button" type="button" data-action="toggle-queue">Queue</button>
						<button class="dmwcfw-panel-button" type="button" data-action="toggle-actions">Ship</button>
					</div>
				</header>
				<div class="dmwcfw-body">
					<aside class="dmwcfw-queue" aria-label="Order queue">
						<div class="dmwcfw-queue__header">
							<div><span class="dmwcfw-eyebrow">Live queue</span><h2>Orders</h2></div>
							<button class="dmwcfw-close-panel" type="button" data-action="close-panels" aria-label="Close queue">×</button>
						</div>
						<nav class="dmwcfw-tabs" data-dmwcfw-tabs aria-label="Order status"></nav>
						<label class="dmwcfw-search">
							<span class="dashicons dashicons-search" aria-hidden="true"></span>
							<span class="screen-reader-text">Search orders</span>
							<input type="search" data-dmwcfw-search placeholder="Customer or order…" autocomplete="off">
							<kbd>/</kbd>
						</label>
						<div class="dmwcfw-queue__summary" data-dmwcfw-queue-summary></div>
						<div class="dmwcfw-order-list" data-dmwcfw-order-list></div>
					</aside>
					<main class="dmwcfw-detail" data-dmwcfw-detail></main>
					<aside class="dmwcfw-action" data-dmwcfw-action aria-label="Fulfillment actions"></aside>
				</div>
				<div class="dmwcfw-panel-scrim" data-action="close-panels"></div>
				<div class="dmwcfw-live-region" data-dmwcfw-live role="status" aria-live="polite"></div>
			</div>`;
      this.render();
    }
    render() {
      this.renderHeader();
      this.renderTabs();
      this.renderQueue();
      this.renderDetail();
      this.renderActions();
    }
    renderHeader() {
      const count = this.root.querySelector("[data-dmwcfw-ready-count]");
      const sync = this.root.querySelector("[data-dmwcfw-sync-label]");
      if (count) {
        count.textContent = String(this.counts.processing);
      }
      if (sync) {
        sync.textContent = this.busy ? "Updating…" : this.lastUpdated ? `Synced ${this.lastUpdated}` : "Connecting…";
      }
      this.root.classList.toggle("is-busy", this.busy);
    }
    renderTabs() {
      const tabs = this.root.querySelector("[data-dmwcfw-tabs]");
      if (!tabs) {
        return;
      }
      const labels = {
        processing: "Ready",
        "on-hold": "On hold",
        completed: "Done"
      };
      tabs.innerHTML = Object.keys(labels).map(
        (status) => `
					<button type="button" data-status="${status}" class="${this.status === status ? "is-active" : ""}" aria-pressed="${this.status === status}">
						${labels[status]} <span>${this.counts[status]}</span>
					</button>`
      ).join("");
    }
    renderQueue() {
      const list = this.root.querySelector("[data-dmwcfw-order-list]");
      const summary = this.root.querySelector("[data-dmwcfw-queue-summary]");
      if (summary) {
        summary.innerHTML = `<strong>${pluralize(this.orders.length, "order")}</strong><span>j / k to move</span>`;
      }
      if (!list) {
        return;
      }
      if (this.busy && this.orders.length === 0) {
        list.innerHTML = Array.from({ length: 4 }, () => '<div class="dmwcfw-order-card dmwcfw-order-card--skeleton"></div>').join("");
        return;
      }
      if (this.orders.length === 0) {
        list.innerHTML = `
				<div class="dmwcfw-empty-queue">
					<span class="dashicons dashicons-yes-alt" aria-hidden="true"></span>
					<strong>${this.search ? "No matching orders" : "Queue clear"}</strong>
					<p>${this.search ? "Try another customer or order number." : "Nothing needs attention in this lane."}</p>
					${this.search ? '<button type="button" data-action="clear-search">Clear search</button>' : ""}
				</div>`;
        return;
      }
      list.innerHTML = this.orders.map((order, index) => {
        const selected = order.id === this.selectedId;
        return `
					<button type="button" class="dmwcfw-order-card ${selected ? "is-selected" : ""}" data-order-id="${order.id}" aria-pressed="${selected}">
						<span class="dmwcfw-order-card__index">${String(index + 1).padStart(2, "0")}</span>
						<span class="dmwcfw-order-card__body">
							<span class="dmwcfw-order-card__top"><strong>#${escapeHtml(order.number)}</strong><b>${escapeHtml(order.total)}</b></span>
							<span class="dmwcfw-order-card__customer">${escapeHtml(order.customer.name)}</span>
							<span class="dmwcfw-order-card__meta"><span>${pluralize(order.itemCount, "item")}</span><span class="${order.isWaiting ? "is-waiting" : ""}">${escapeHtml(order.age)}</span></span>
						</span>
					</button>`;
      }).join("");
    }
    renderDetail() {
      const detail = this.root.querySelector("[data-dmwcfw-detail]");
      const order = this.selectedOrder();
      if (!detail) {
        return;
      }
      if (!order) {
        detail.innerHTML = `
				<div class="dmwcfw-empty-detail">
					<span class="dmwcfw-empty-detail__stamp">QUEUE</span>
					<h2>${this.busy ? "Loading the dispatch desk…" : "Choose an order"}</h2>
					<p>${this.busy ? "Pulling the latest information from WooCommerce." : "Select an order from the queue to start packing."}</p>
				</div>`;
        return;
      }
      const items = order.items.map(
        (item) => `
					<li class="dmwcfw-line-item">
						<span class="dmwcfw-line-item__thumb" aria-hidden="true">${escapeHtml(item.name.charAt(0).toUpperCase())}</span>
						<span class="dmwcfw-line-item__name"><strong>${escapeHtml(item.name)}</strong><small>${item.sku ? `SKU ${escapeHtml(item.sku)}` : "No SKU"}</small></span>
						<span class="dmwcfw-line-item__qty"><small>Qty</small><strong>${item.quantity}</strong></span>
						<span class="dmwcfw-line-item__total">${escapeHtml(item.total)}</span>
					</li>`
      ).join("");
      const notes = order.notes.length ? order.notes.map(
        (note) => `
							<li><span></span><div><strong>${escapeHtml(note.content)}</strong><small>${escapeHtml(note.date)}</small></div></li>`
      ).join("") : '<li class="dmwcfw-timeline__empty"><span></span><div><strong>No internal notes yet</strong><small>Order updates will appear here.</small></div></li>';
      detail.innerHTML = `
			<div class="dmwcfw-detail__inner">
				<div class="dmwcfw-order-heading">
					<div>
						<span class="dmwcfw-eyebrow">Pack order</span>
						<h1>#${escapeHtml(order.number)}</h1>
						<p>Placed ${escapeHtml(order.createdLabel)} · ${escapeHtml(order.age)}</p>
					</div>
					<span class="dmwcfw-status-pill dmwcfw-status-pill--${escapeHtml(order.status)}">${escapeHtml(order.statusLabel)}</span>
				</div>
				<section class="dmwcfw-customer-strip" aria-label="Customer">
					<span class="dmwcfw-avatar" aria-hidden="true">${escapeHtml(initials(order.customer.name))}</span>
					<div><small>Shipping to</small><strong>${escapeHtml(order.customer.name)}</strong></div>
					<div><small>Email</small><a href="mailto:${escapeHtml(order.customer.email)}">${escapeHtml(order.customer.email || "Not provided")}</a></div>
					<div><small>Phone</small><span>${escapeHtml(order.customer.phone || "Not provided")}</span></div>
				</section>
				<section class="dmwcfw-section dmwcfw-pick-list">
					<div class="dmwcfw-section__heading"><div><span class="dmwcfw-eyebrow">Pick list</span><h2>${pluralize(order.itemCount, "item")}</h2></div><span class="dmwcfw-section__rule"></span></div>
					<ul>${items}</ul>
					<div class="dmwcfw-order-total"><span>Order total</span><strong>${escapeHtml(order.total)}</strong></div>
				</section>
				<section class="dmwcfw-detail-grid">
					<div class="dmwcfw-info-card">
						<span class="dmwcfw-eyebrow">Checkout</span>
						<dl><div><dt>Payment</dt><dd>${escapeHtml(order.paymentMethod || "Not recorded")}</dd></div><div><dt>Delivery</dt><dd>${escapeHtml(order.shipping.method || "No shipping method")}</dd></div></dl>
					</div>
					<div class="dmwcfw-info-card dmwcfw-info-card--timeline">
						<span class="dmwcfw-eyebrow">Order trail</span>
						<ul class="dmwcfw-timeline">${notes}</ul>
					</div>
				</section>
			</div>`;
    }
    renderActions() {
      const panel = this.root.querySelector("[data-dmwcfw-action]");
      const order = this.selectedOrder();
      if (!panel) {
        return;
      }
      if (!order) {
        panel.innerHTML = `
				<div class="dmwcfw-action__header"><div><span class="dmwcfw-eyebrow">Next action</span><h2>Fulfill</h2></div><button class="dmwcfw-close-panel" type="button" data-action="close-panels" aria-label="Close actions">×</button></div>
				<div class="dmwcfw-action__empty"><span class="dashicons dashicons-archive" aria-hidden="true"></span><p>Select an order to see shipping actions.</p></div>`;
        return;
      }
      const address = order.shipping.lines.map(escapeHtml).join("<br>");
      const isCompleted = order.status === "completed";
      const isOnHold = order.status === "on-hold";
      const confirming = this.confirmCompleteId === order.id;
      panel.innerHTML = `
			<div class="dmwcfw-action__header">
				<div><span class="dmwcfw-eyebrow">Next action</span><h2>${isCompleted ? "Completed" : isOnHold ? "Resolve hold" : "Ship order"}</h2></div>
				<button class="dmwcfw-close-panel" type="button" data-action="close-panels" aria-label="Close actions">×</button>
			</div>
			<ol class="dmwcfw-progress" aria-label="Fulfillment progress">
				<li class="is-done"><span>1</span><div><strong>Paid</strong><small>Payment captured</small></div></li>
				<li class="${isCompleted ? "is-done" : "is-current"}"><span>2</span><div><strong>Pick &amp; pack</strong><small>${pluralize(order.itemCount, "item")} to prepare</small></div></li>
				<li class="${isCompleted ? "is-done" : ""}"><span>3</span><div><strong>Dispatch</strong><small>${escapeHtml(order.shipping.method || "Add tracking in full order")}</small></div></li>
			</ol>
			<section class="dmwcfw-address-card">
				<div class="dmwcfw-address-card__top"><span class="dmwcfw-eyebrow">Shipping label</span><button type="button" data-action="copy-address">Copy</button></div>
				<address>${address || "No shipping address supplied."}</address>
				${order.customerNote ? `<p><strong>Customer note</strong>${escapeHtml(order.customerNote)}</p>` : ""}
			</section>
			<div class="dmwcfw-primary-actions">
				${this.actionButtons(order, confirming)}
			</div>
			<a class="dmwcfw-full-order" href="${escapeHtml(order.editUrl)}"><span>Open full WooCommerce order</span><span aria-hidden="true">↗</span></a>
			<div class="dmwcfw-shortcuts"><span><kbd>J</kbd><kbd>K</kbd> Move queue</span><span><kbd>R</kbd> Refresh</span></div>`;
    }
    actionButtons(order, confirming) {
      if (order.status === "completed") {
        return '<button class="dmwcfw-primary-button" type="button" data-action="change-status" data-next-status="processing">Return to ready queue</button>';
      }
      if (confirming) {
        return `
				<div class="dmwcfw-confirm"><strong>Everything packed?</strong><span>This completes order #${escapeHtml(order.number)}.</span></div>
				<button class="dmwcfw-primary-button is-confirming" type="button" data-action="change-status" data-next-status="completed">Yes, complete order</button>
				<button class="dmwcfw-secondary-button" type="button" data-action="cancel-complete">Not yet</button>`;
      }
      return `
			<button class="dmwcfw-primary-button" type="button" data-action="prepare-complete">Mark packed &amp; complete</button>
			<button class="dmwcfw-secondary-button" type="button" data-action="change-status" data-next-status="${order.status === "on-hold" ? "processing" : "on-hold"}">${order.status === "on-hold" ? "Return to ready queue" : "Put order on hold"}</button>`;
    }
    announce(message) {
      const region = this.root.querySelector("[data-dmwcfw-live]");
      if (!region) {
        return;
      }
      region.textContent = message;
      region.classList.add("is-visible");
      window.setTimeout(() => region.classList.remove("is-visible"), 3600);
    }
    selectRelative(offset) {
      if (this.orders.length === 0) {
        return;
      }
      const current = this.orders.findIndex((order) => order.id === this.selectedId);
      const index = Math.max(0, Math.min(this.orders.length - 1, current + offset));
      this.selectedId = this.orders[index].id;
      this.confirmCompleteId = null;
      this.renderQueue();
      this.renderDetail();
      this.renderActions();
      this.root.querySelector(`[data-order-id="${this.selectedId}"]`)?.scrollIntoView({ block: "nearest" });
    }
  }
  function mountWorkbench(body, api2) {
    const root = body.querySelector("[data-dmwcfw-workspace]");
    if (!root || root.dataset.dmwcfwMounted === "true") {
      return;
    }
    root.dataset.dmwcfwMounted = "true";
    try {
      new DispatchWorkbench(root, getConfig(api2)).start();
    } catch (error) {
      root.innerHTML = `<div class="dmwcfw-fatal"><strong>Woo Dispatch could not start.</strong><p>${escapeHtml(error instanceof Error ? error.message : "Configuration unavailable.")}</p></div>`;
    }
  }
  function whenDesktopReady(api2, callback) {
    if (typeof api2.ready === "function") {
      api2.ready(callback);
    } else if (typeof api2.whenReady === "function") {
      api2.whenReady(callback);
    } else {
      callback();
    }
  }
  const api = window.wp?.desktop;
  if (api) {
    window.desktopModeNativeWindows = window.desktopModeNativeWindows ?? {};
    window.desktopModeNativeWindows[WINDOW_ID] = (body) => mountWorkbench(body, api);
    whenDesktopReady(api, () => {
      api.registerCommand?.({
        slug: "woocommerce_fulfillment_workbench",
        label: translate("Open Woo Dispatch"),
        description: translate("Work the live order queue from one focused surface."),
        icon: "dashicons-store",
        owner: COMMAND_OWNER,
        run: (_args, context) => {
          api.openWindow?.(WINDOW_ID);
          context.close();
        }
      });
    });
  }
})();
